 const descriptions={apoios:'Cada pedido tem uma etapa, um responsável e um próximo passo.',voluntarios:'Acompanhe os interessados, a avaliação, a aprovação e o vínculo com os projetos.',equipe:'Organize funções, contatos e disponibilidade. Estes registros não concedem acesso ao painel.',familias:'Crie referências familiares para conectar apoios e atividades sem repetir dados.',agenda:'Vincule pessoa, projeto, responsável e participantes. Só atividades realizadas alimentam a execução confirmada.'};
 const supportStates={recebido:'Recebido',em_acolhimento:'Em acolhimento',em_analise:'Em análise',encaminhado:'Encaminhado',agendado:'Agendado',concluido:'Concluído',lista_espera:'Lista de espera',arquivado:'Arquivado'};
 const volunteerStates={interessado:'Interessado',em_avaliacao:'Em avaliação',aprovado:'Aprovado',vinculado:'Vinculado a projeto',ativo:'Ativo',inativo:'Inativo'};
 const sessionStates={agendado:'Agendado',realizado:'Realizado',cancelado:'Cancelado',falta:'Falta'};
 const hints={apoios:'O pedido não garante vaga ou atendimento imediato. Defina os vínculos conforme a disponibilidade confirmada. Não registre diagnósticos ou documentos.',voluntarios:'A aprovação e a vinculação dependem da avaliação da equipe. Voluntário interessado ainda não é participante ativo.',equipe:'Este cadastro organiza a equipe e a disponibilidade informada. Ele não cria conta, envia convite nem concede acesso administrativo.',familias:'Use uma referência familiar e um contato necessário ao acompanhamento. Não registre documentos, diagnósticos ou informações de saúde.',agenda:'Escolha o responsável e os vínculos. Registre “Realizado” somente depois da atividade. A mesma ocorrência deve ser corrigida pelo botão Editar para evitar duplicidade.'};
 let current='apoios',data={apoios:[],voluntarios:[],equipe:[],areasAgenda:[],familias:[],agenda:[],entries:[],projects:[],publicProjects:[],pending:{apoios:[],voluntarios:[]}},loaded=false,loading=false,refreshQueued=false,editing=null,origin=null,saving=false;
 function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
 async function api(path,body){const response=await fetch(path,body===undefined?{cache:'no-store'}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let result;try{result=await response.json();}catch{throw Error('O servidor não respondeu como esperado. Recarregue os dados antes de tentar novamente.');}if(!response.ok)throw Error(result.error||'Não foi possível concluir.');return result;}
 async function allEntries(){const rows=[],seen=new Set();let page=1;while(true){const result=await api('/api/admin/entries?pagina='+page);for(const row of result.items){if(!seen.has(row.id)){seen.add(row.id);rows.push(row);}}if(page*50>=result.total)break;if(!result.items.length||page>=10000)throw Error('A lista de contatos não pôde ser carregada por completo.');page++;}return rows;}
 function stateMap(type=current){return type==='apoios'?supportStates:type==='voluntarios'?volunteerStates:type==='agenda'?sessionStates:type==='equipe'?{ativo:'Ativo',inativo:'Inativo'}:{};}
