 function renderPending(search){const wrapper=$('#op-incoming'),list=$('#op-incoming-list');list.replaceChildren();if(!['apoios','voluntarios'].includes(current)){wrapper.hidden=true;return;}const rows=(data.pending[current]||[]).filter(row=>!search||(row.nome+' '+row.contato).toLocaleLowerCase('pt-BR').includes(search));wrapper.hidden=!rows.length;$('#op-incoming-title').textContent=current==='apoios'?'Pedidos recebidos aguardando acompanhamento':'Voluntários interessados aguardando avaliação';for(const row of rows){const line=el('div',undefined,'op-incoming-row'),copy=el('div');copy.append(el('strong',row.nome),el('small',row.contato));const button=el('button','Iniciar acompanhamento','button secondary');button.type='button';button.onclick=()=>open(current,{cadastro_id:row.cadastro_id,etapa:current==='apoios'?'recebido':'interessado'});line.append(copy,button);list.append(line);}}
 function changeTab(type){current=type;for(const button of root.querySelectorAll('[data-op-tab]')){const active=button.dataset.opTab===type;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));}$('#op-content').setAttribute('aria-labelledby','op-tab-'+type);$('#op-state').replaceChildren(new Option('Todas',''));for(const[key,label]of Object.entries(stateMap(type)))$('#op-state').add(new Option(label,key));$('#op-state').disabled=type==='familias';$('#op-search').value='';render();}
 async function refresh(){if(loading){refreshQueued=true;return;}loading=true;$('#op-status').textContent='Carregando acompanhamento…';$('#op-new').disabled=true;try{const [team,families,support,volunteers,sessions,entries,projects,publicProjects,pending,summary]=await Promise.all([api('/api/admin/operacao-equipe'),api('/api/admin/operacao-familias'),api('/api/admin/operacao-apoios'),api('/api/admin/operacao-voluntarios'),api('/api/admin/operacao-agenda'),allEntries(),api('/api/admin/projetos'),api('/api/admin/projetos-site'),api('/api/admin/operacao-pendencias'),api('/api/admin/operacao-resumo?periodo='+$('#op-metrics-period').value)]);data={equipe:team.items,familias:families.items,apoios:support.items,voluntarios:volunteers.items,agenda:sessions.items,areasAgenda:sessions.areas_responsaveis||[],entries,projects:projects.items,publicProjects:publicProjects.items,pending,summary};loaded=true;render();$('#op-new').disabled=false;return true;}catch(error){$('#op-status').textContent=error.message;loaded=false;return false;}finally{loading=false;if(refreshQueued){refreshQueued=false;refresh();}}}
 function field(name,label,type='text',options={}){const wrap=el('label',label),input=document.createElement(type==='textarea'?'textarea':type==='select'?'select':'input');if(type!=='textarea'&&type!=='select')input.type=type;input.name=name;input.id='op-field-'+name;wrap.htmlFor=input.id;if(options.items)for(const[value,text]of options.items)input.add(new Option(text,value));if(options.value!==undefined)input.value=options.value??'';for(const key of ['required','minLength','maxLength','min','max','step','placeholder'])if(options[key]!==undefined)input[key]=options[key];wrap.append(input);if(options.hint)wrap.append(el('small',options.hint,'field-hint'));return wrap;}
